(1051429, 126619, 21202, '<td valign="top">Nice lesson in reflected light.  The border helps a lot.  Somehow though, perhaps too much neatimage, but the apple appears flattened where the yellow rellects.  A 7.</td>', 'Nice lesson in reflected light.  The border helps a lot.  Somehow though, perhaps too much neatimage, but the apple appears flattened where the yellow rellects.  A 7.', '2004-12-08 01:16:03.000000', NULL, 1),
(1051430, 125796, 27293, '<td valign="top">Oh come on, can''t just reproduce a high-ranking image from another challenge... gotta be more creative. Otherwise, awful technique and questionable composition.</td>', 'Oh come on, can''t just reproduce a high-ranking image from another challenge... gotta be more creative. Otherwise, awful technique and questionable composition.', '2004-12-08 01:16:32.000000', NULL, 1),
(1051431, 125530, 21202, '<td valign="top">Quite nice.   A 6.</td>', 'Quite nice.   A 6.', '2004-12-08 01:16:59.000000', NULL, 1),
