INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1052068, 126654, 12108, '<td valign="top">good shot, seems that the focus is a little soft and the light source on the lower part of the glass is distracting.(5)</td>', 'good shot, seems that the focus is a little soft and the light source on the lower part of the glass is distracting.(5)', '2004-12-08 11:49:19.000000', NULL, 1),
(1052069, 126622, 24065, '<td valign="top">This was a good idea and I like the composition.  I''m guessing from your photo that the light wasn''t diffused.  It may also be the characterisitcs of the mango, but it looks a little shallow on dof.  Hope this is helpful :)</td>', 'This was a good idea and I like the composition.  I''m guessing from your photo that the light wasn''t diffused.  It may also be the characterisitcs of the mango, but it looks a little shallow on dof.  Hope this is helpful :)', '2004-12-08 11:49:29.000000', NULL, 1),
(1052072, 126306, 5364, '<td valign="top">Having a green bowl isn''t doing you any favours here - maybe just having the lemons piled on the white background would have been better.</td>', 'Having a green bowl isn''t doing you any favours here - maybe just having the lemons piled on the white background would have been better.', '2004-12-08 11:50:28.000000', NULL, 1),
