(1052492, 126799, 14621, '<td valign="top">Really artistic  nice compo .... 7</td>', 'Really artistic  nice compo .... 7', '2004-12-08 14:41:29.000000', NULL, 1),
(1052493, 125870, 12733, '<td valign="top">The picture is clearly posed, so why not have her open her eyes and appear to be relaxing among the leaves? The pose, along with the title, makes what could be a cheerful and pretty shot just a bit creepy.</td>', 'The picture is clearly posed, so why not have her open her eyes and appear to be relaxing among the leaves? The pose, along with the title, makes what could be a cheerful and pretty shot just a bit creepy.', '2004-12-08 14:41:57.000000', NULL, 1),
