INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1053398, 126286, 22305, '<td valign="top">I think this would have been better if you used indirect lighting.</td>', 'I think this would have been better if you used indirect lighting.', '2004-12-08 22:11:57.000000', NULL, 1),
(1053401, 125977, 22305, '<td valign="top">Too washed out for me.</td>', 'Too washed out for me.', '2004-12-08 22:15:17.000000', NULL, 1),
(1053402, 126762, 19978, '<td valign="top">This photograph is truly a work of art. I''d love to know how it is lit. The delicate lines and soft foreground shading, contrasting with sharp shadows behind - it nearly takes my breath away. You should be proud of this one. I aspire to such creativity...!</td>', 'This photograph is truly a work of art. I''d love to know how it is lit. The delicate lines and soft foreground shading, contrasting with sharp shadows behind - it nearly takes my breath away. You should be proud of this one. I aspire to such creativity...!', '2004-12-08 22:16:30.000000', NULL, 1),
(1053403, 126864, 22305, '<td valign="top">Did you try to crop out the bottom half of this. I find it too bland.</td>', 'Did you try to crop out the bottom half of this. I find it too bland.', '2004-12-08 22:16:31.000000', NULL, 1),
