(1055028, 126807, 21202, '<td valign="top">What a nice piece of real estate, even if the morning fog is still lingering at sundown.The shadow of the other building on the house is a little unfortunate.  I would be tempted to crop the right side just to the right of the windows.  A 10.</td>', 'What a nice piece of real estate, even if the morning fog is still lingering at sundown.The shadow of the other building on the house is a little unfortunate.  I would be tempted to crop the right side just to the right of the windows.  A 10.', '2004-12-09 19:53:59.000000', NULL, 1),
(1055030, 126387, 20779, '<td valign="top">I can see this ribboning. Very well done, very "DPC". Just noticed the little smiley on this round. Too bad about the hot pixel.</td>', 'I can see this ribboning. Very well done, very "DPC". Just noticed the little smiley on this round. Too bad about the hot pixel.', '2004-12-09 19:55:02.000000', NULL, 1),
(1055031, 126026, 28141, '<td valign="top">Good colors, but I hate square crops.</td>', 'Good colors, but I hate square crops.', '2004-12-09 19:55:04.000000', NULL, 1),
(1055034, 126800, 20779, '<td valign="top">I don''t know why, but the toys are working for me in this challenge. Very well done and fun to look at!</td>', 'I don''t know why, but the toys are working for me in this challenge. Very well done and fun to look at!', '2004-12-09 19:56:09.000000', NULL, 1),
(1055036, 126582, 28141, '<td valign="top">I don''t like the border.</td>', 'I don''t like the border.', '2004-12-09 19:56:48.000000', NULL, 1),
(1055038, 125642, 28141, '<td valign="top">Good looking shot, but I hate square crops, and it doesn''t need a border.</td>', 'Good looking shot, but I hate square crops, and it doesn''t need a border.', '2004-12-09 19:57:24.000000', NULL, 1),
(1055039, 126381, 20779, '<td valign="top">My favorite of the citrus slice/glass shots. I love the close-in crop, tilt and de-sat. 8.</td>', 'My favorite of the citrus slice/glass shots. I love the close-in crop, tilt and de-sat. 8.', '2004-12-09 19:57:28.000000', NULL, 1),
(1055041, 125765, 28141, '<td valign="top">Nice image...loose the border though.</td>', 'Nice image...loose the border though.', '2004-12-09 19:58:15.000000', NULL, 1),
(1055042, 126064, 20779, '<td valign="top">Very engaging shot. One of my favorites, and very original. Great job!</td>', 'Very engaging shot. One of my favorites, and very original. Great job!', '2004-12-09 19:58:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1055044, 126256, 20779, '<td valign="top">Gotta love it. Great shot.</td>', 'Gotta love it. Great shot.', '2004-12-09 19:58:49.000000', NULL, 1),
