(1057486, 126755, 27994, '<td valign="top">very nice!"</td>', 'very nice!"', '2004-12-11 17:25:44.000000', NULL, 1),
(1057488, 126422, 24065, '<td valign="top">This is so pretty, and I almost missed it.</td>', 'This is so pretty, and I almost missed it.', '2004-12-11 17:26:03.000000', NULL, 1),
(1057489, 126889, 24065, '<td valign="top">I like the colors and composition, but especially your choice for dof.  Very nice.</td>', 'I like the colors and composition, but especially your choice for dof.  Very nice.', '2004-12-11 17:26:46.000000', NULL, 1),
