(1057492, 126387, 27994, '<td valign="top">a different shot: <br/> <br/></td>', 'a different shot:  ', '2004-12-11 17:30:47.000000', NULL, 1),
(1057493, 126423, 24065, '<td valign="top">I really like macro abstracts.  I''ll be interested to see how well this is received in the challenge.  But you''ve got my vote :)  BOL</td>', 'I really like macro abstracts.  I''ll be interested to see how well this is received in the challenge.  But you''ve got my vote :)  BOL', '2004-12-11 17:31:33.000000', NULL, 1),
(1057494, 126743, 24065, '<td valign="top">Very nice.  I do find the tip of the nose a bit distracting and think a closer crop at the bottom would have helped.  But I haven''t figured the voters out, so don''t put too much stock in my opinion.  :)  The focus in the rest of the photo is fantastic!  BOL</td>', 'Very nice.  I do find the tip of the nose a bit distracting and think a closer crop at the bottom would have helped.  But I haven''t figured the voters out, so don''t put too much stock in my opinion.  :)  The focus in the rest of the photo is fantastic!  BOL', '2004-12-11 17:34:00.000000', NULL, 1),
(1057495, 125818, 24065, '<td valign="top">I like it!  :)</td>', 'I like it!  :)', '2004-12-11 17:34:35.000000', NULL, 1);
