(1057518, 126865, 23456, '<td valign="top">Good concept, balloons always look great in the sky !</td>', 'Good concept, balloons always look great in the sky !', '2004-12-11 17:58:54.000000', NULL, 1),
(1057524, 125345, 23456, '<td valign="top">unusual concept but i like it , well done!</td>', 'unusual concept but i like it , well done!', '2004-12-11 18:02:50.000000', NULL, 1),
